from lib import *
S = SS('f48')
R = J('f48'); sz = R['size']; rs = R['resend']
steps = [
    step(f"最简单的 session(user = ann、n = 1):Set-Cookie: session=eyJu…; HttpOnly; Path=/。值分 3 段,没有压缩,不需要密钥就能解开 payload:{R['dec'][2]},签发时间 {R['dec'][3]}。session cookie 的数据放在客户端,签名只防篡改,不防阅读。", t=tl(S(1)), done=lidx(S(1), 'Set-Cookie:', 'cookie 值分'), kv=KV([['结构', 'payload.timestamp.signature'], ['payload', '{\"n\":1,\"user\":\"ann\"} 明文'], ['属性', 'HttpOnly; Path=/']], ['payload'])),
    step("非 JSON 类型用带标记的 JSON(TaggedJSONSerializer):标记是「空格 + 单字母」的键。bytes → {\" b\": base64};datetime → {\" d\": HTTP 日期};tuple → {\" t\": […]};UUID → {\" u\": 无连字符的十六进制};Markup → {\" m\": …};嵌套在列表里的元组同样被标记。读回来类型保持:bytes、datetime、list、Markup、tuple、UUID。", t=tl(S(2)), done=lidx(S(2), 'payload ='), mark=lidx(S(2), 'session 里的真实类型'), kv=KV([['bytes', '{\" b\": …}'], ['datetime', '{\" d\": …}'], ['tuple', '{\" t\": …}'], ['UUID', '{\" u\": …}']], ['tuple'])),
    step("permanent 与否:不 permanent 的 session 的 Set-Cookie 只有 HttpOnly; Path=/(浏览器会话 cookie,关浏览器就没了);session.permanent = True 才有 Expires=…(PERMANENT_SESSION_LIFETIME = 31 天,Expires 是 31 天后)。", t=tl(S(3)), done=lidx(S(3), '非 permanent:', 'PERMANENT_SESSION_LIFETIME'), mark=lidx(S(3), 'permanent   :'), kv=KV([['非 permanent', '无 Expires(会话 cookie)'], ['permanent', 'Expires = 31 天后']], ['permanent'])),
    step(f"什么时候重发 Set-Cookie:非 permanent 的 session 只读不发({'发' if rs['非 permanent:只读一下'] else '不发'}),修改了才发({'发' if rs['非 permanent:修改'] else '不发'});permanent 的 session 只读也发({'发' if rs['permanent:只读一下'] else '不发'}),因为 SESSION_REFRESH_EACH_REQUEST 默认为 True 要刷新过期时间;把它设成 False 后只读不发({'发' if rs['permanent + REFRESH=False:只读一下'] else '不发'})。", t=tl(S(4)), done=lidx(S(4), '非 permanent'), mark=lidx(S(4), 'permanent:只读一下', 'REFRESH=False'), kv=KV([['非 permanent 只读', '不发'], ['非 permanent 修改', '发'], ['permanent 只读', '发(刷新过期时间)'], ['REFRESH_EACH_REQUEST=False', '不发']], ['permanent 只读'])),
    step("登出 session.clear():发出 Set-Cookie: session=; Expires=Thu, 01 Jan 1970 00:00:00 GMT; Max-Age=0; HttpOnly; Path=/ —— 清空 session 等于删除 cookie。", t=tl(S(5)), done=lidx(S(5), 'Set-Cookie:'), kv=KV([['session.clear()', '值为空、Max-Age=0 的 Set-Cookie']], ['session.clear()'])),
    step(f"大小与压缩(值都以 . 开头,即 zlib 压缩过):随机十六进制 100 字符 → cookie {sz['随机十六进制 100'][0]} 字节;1000 → {sz['随机十六进制 1000'][0]};3000 → {sz['随机十六进制 3000'][0]};5000 → {sz['随机十六进制 5000'][0]};8000 → {sz['随机十六进制 8000'][0]} 字节并触发 1 条超过 4093 字节的警告(十六进制每字符只有 4 位信息,所以压缩后约缩小到五分之四)。重复的 x 100 / 1000 / 5000 字符 → {sz['重复的 x 100'][0]} / {sz['重复的 x 1000'][0]} / {sz['重复的 x 5000'][0]} 字节。session 里放大对象很快就超出 cookie 上限。", t=tl(S(6)), done=lidx(S(6), '随机十六进制     100', '随机十六进制    1000'), mark=lidx(S(6), '随机十六进制    8000', '重复的 x'), kv=KV([['随机内容 5000 字符', f"{sz['随机十六进制 5000'][0]} 字节"], ['8000 字符', f"{sz['随机十六进制 8000'][0]} 字节 + 警告"], ['重复内容 5000 字符', f"{sz['重复的 x 5000'][0]} 字节"]], ['8000 字符'])),
    step("篡改 cookie:原样请求得到 {'n': 1, 'user': 'ann'};改 payload 的一个字符、或换成用别的密钥签的 token,请求仍然是 200,但 session 是空字典 {} —— 签名不对不会抛异常,而是静默当作没有 session(没登录)。", t=tl(S(7)), done=lidx(S(7), '原样'), mark=lidx(S(7), '改 payload', '换成别的密钥签的'), kv=KV([['原样', '读到 session'], ['篡改或换密钥', '空 session {},不报错']], ['篡改或换密钥'])),
    step(f"Flask 用的签名参数:salt = {R['si'][0]}、key_derivation = {R['si'][1]}(HMAC 派生,与上一篇里手算的 django-concat 默认值不同)、digest_method = {R['si'][2]}(SHA-1 的惰性包装)、serializer = {R['si'][3]}。", t=tl(S(8)), done=lidx(S(8), 'salt ='), kv=KV([['salt', R['si'][0]], ['key_derivation', R['si'][1]], ['serializer', R['si'][3]]], ['key_derivation'])),
]
A = mkartf('f48', 48, 'Flask,Session,Cookie,签名,真实验证,动画演示',
    '解开 Flask session cookie:payload.timestamp.signature 三段,payload 不需要密钥就能读;TaggedJSON 对 bytes/datetime/tuple/UUID/Markup 的标记;permanent 才有 Expires;什么时候重发 Set-Cookie;超过 4093 字节警告;篡改后静默得到空 session;salt=cookie-session、key_derivation=hmac。',
    'session 里的东西到底存在哪?装的是什么格式?不用密钥能不能读出来?为什么我改了 session 却没有新的 Set-Cookie?这篇把 cookie 解开,逐项验证。',
    [('0 个', '读取 session cookie 的 payload 所需的密钥个数(只需 base64,可明文读取)'), ('4093', '超过它会触发警告的 cookie 大小(字节)'), ('{}', '签名不对时读到的 session(不抛异常)')],
    [('一个 session cookie', '<p>上一篇:<a href="flask-signed-cookie.html">Signed Cookie</a>;下一篇:<a href="flask-range-request.html">Range 请求与断点下载</a>;SECRET_KEY 的专题:<a href="flask-secret-key-usage.html">SECRET_KEY 的用途</a>;安全属性:<a href="flask-session-cookie-security.html">Session Cookie 安全属性</a>。</p>'), ('TaggedJSON', None), ('permanent', None), ('重发 Set-Cookie', None), ('登出', None), ('大小与压缩', None), ('篡改', None), ('签名参数', None)],
    steps, [ENV_F, '没有验证:服务端 session(Flask-Session 等扩展)与客户端 session 的对比、SESSION_COOKIE_PARTITIONED、SECRET_KEY_FALLBACKS 在 session 上的轮换(见第 187 篇)、session 在多个 worker 之间共享(客户端 session 天然共享,只要密钥相同)'], 'Session Cookie')
